let DATA={asr:[],tts:[]};
let rankingMetric={asr:'wer',tts:'mos'};
const LOWER_IS_BETTER=new Set(['wer','cer','rtf','latency','latency_ms','cost','cost_per_hour','memory','params']);
const METRIC_UNITS={wer:'%',cer:'%',mos:'/ 5',sim:'',rtf:'×',latency:' ms',latency_ms:' ms',accuracy:'%',pesq:'',stoi:'',sisdr:' dB',sdr:' dB'};
const METRIC_NAMES={wer:'词错误率',cer:'字错误率',mos:'自然度',sim:'说话人相似度',rtf:'实时率',latency_ms:'推理延迟'};
const COLORS=['#0b9b83','#6e5bd9','#d87339'];
const RANK_MOVEMENT={'Paraformer-Large':1,'Seed-ASR':-1,'Whisper Large-v3':0,'SenseVoice-Large':1,'Google Chirp 3':-1,'Qwen-Audio ASR':2,'Azure Speech':-1,'NVIDIA Canary':-1,'Deepgram Nova-3':1,'Moonshine Base':-1,'CosyVoice 2':1,'Eleven v3':-1,'Seed-TTS':1,'Fish Speech 1.5':-1,'GPT-SoVITS':0,'Azure Neural TTS':1,'MiniMax Speech-02':-1,'F5-TTS':1,'XTTS-v2':-1,'Google Cloud TTS':0};
const metricLabel=key=>String(key||'score').toUpperCase();
const metricArrow=key=>LOWER_IS_BETTER.has(String(key).toLowerCase())?'↓':'↑';
const metricUnit=key=>METRIC_UNITS[String(key).toLowerCase()]??'';
const metricValue=(model,key)=>Number(model.metrics?.[key]??model.score);
const sortModels=(models,key)=>[...models].sort((a,b)=>LOWER_IS_BETTER.has(key)?metricValue(a,key)-metricValue(b,key):metricValue(b,key)-metricValue(a,key));
const formatMetric=(value,key)=>`${Number(value).toFixed(key==='sim'?3:2)}${metricUnit(key)}`;
const esc=value=>String(value??'').replace(/[&<>\"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[ch]));

let task='asr';
const selected=new Set();
const body=document.querySelector('#leaderboardBody');
const typeFilter=document.querySelector('#typeFilter');
const datasetFilter=document.querySelector('#datasetFilter');

function setTheme(next){document.documentElement.dataset.theme=next;localStorage.setItem('speechbench-theme',next);document.querySelectorAll('.theme-toggle').forEach(button=>button.setAttribute('aria-label',next==='light'?'切换至暗色主题':'切换至浅色主题'))}
setTheme(localStorage.getItem('speechbench-theme')||'light');
function toggleTheme(){setTheme(document.documentElement.dataset.theme==='light'?'dark':'light')}
function rankMotion(name,rank){const delta=RANK_MOVEMENT[name]||0;return `<span class="rank-stack"><b class="rank-value">${String(rank).padStart(2,'0')}</b>${delta?`<small class="rank-delta ${delta>0?'up':'down'}"><i>${delta>0?'↑':'↓'}</i>${Math.abs(delta)}</small>`:'<small class="rank-delta stable">—</small>'}</span>`}
function qualityPercent(value,values,key){const min=Math.min(...values),max=Math.max(...values);if(max===min)return 100;return Math.round((LOWER_IS_BETTER.has(key)?(max-value)/(max-min):(value-min)/(max-min))*76+24)}
function magnitudePercent(value,values){const min=Math.min(...values),max=Math.max(...values);if(max===min)return 100;return Math.round((value-min)/(max-min)*70+30)}

function datasetMetricKey(group,result){const aggregateMetric=rankingMetric[group];return result.metrics[aggregateMetric]!=null?aggregateMetric:(group==='asr'?(result.metrics.wer!=null?'wer':'cer'):(result.metrics.mos!=null?'mos':'sim'))}
function renderTable(){
  const aggregateMetric=rankingMetric[task],dataset=datasetFilter.value;
  const entries=DATA[task].map(model=>{if(dataset==='综合评测')return {model,key:aggregateMetric,value:metricValue(model,aggregateMetric)};const result=model.datasets.find(d=>d.name===dataset);if(!result)return null;const key=datasetMetricKey(task,result);return {model,key,value:Number(result.metrics[key])}}).filter(Boolean).filter(x=>typeFilter.value==='all'||x.model.kind===typeFilter.value);
  const key=entries[0]?.key||aggregateMetric;entries.sort((a,b)=>LOWER_IS_BETTER.has(key)?a.value-b.value:b.value-a.value);document.querySelector('#primaryMetric').textContent=`${metricLabel(key)} ${metricArrow(key)}`;
  if(!entries.length){body.innerHTML='<tr><td colspan="4" class="empty-state">当前筛选条件下无模型数据</td></tr>';return}
  const scoreValues=entries.map(x=>x.value);
  body.innerHTML=entries.map(({model:m,value,key},i)=>{const level=qualityPercent(value,scoreValues,key);return `<tr data-model="${esc(m.name)}" tabindex="0"><td><span class="rank ${i<3?'top':''}">${rankMotion(m.name,i+1)}</span></td><td><div class="model">${logoMarkup(m)}<span><b>${esc(m.name)}</b><small><i class="type-dot ${m.kind}"></i>${esc(m.org)}</small></span></div></td><td><div class="score-viz ${i===0?'best':''}" style="--level:${level}%;--heat:${Math.round(level/7)}%"><span>${formatMetric(value,key)}</span><i></i></div></td><td><input class="compare-check" type="checkbox" aria-label="将 ${esc(m.name)} 加入对比" data-name="${esc(m.name)}" ${selected.has(m.name)?'checked':''}></td></tr>`}).join('');
  bindLogoFallback(body);body.querySelectorAll('.compare-check').forEach(el=>el.addEventListener('change',onCompare));body.querySelectorAll('tr[data-model]').forEach(row=>{row.addEventListener('click',e=>{if(!e.target.classList.contains('compare-check'))openModel(row.dataset.model)});row.addEventListener('keydown',e=>{if(e.key==='Enter')openModel(row.dataset.model)})});
}

function setTask(next){const chosen=selected.size?findModel([...selected][0]):null;if(chosen&&chosen.group!==next){selected.clear();renderCompareTray()}task=next;document.querySelector('#taskTitle').textContent=task==='asr'?'语音识别':'语音合成';document.querySelectorAll('.segmented [data-task]').forEach(b=>b.classList.toggle('active',b.dataset.task===task));updateDatasetFilter();renderTable();renderTop10()}
function updateDatasetFilter(){const current=datasetFilter.value,datasets=[...new Set(DATA[task].flatMap(m=>m.datasets.map(d=>d.name)))];datasetFilter.innerHTML='<option>综合评测</option>'+datasets.map(name=>`<option>${esc(name)}</option>`).join('');if(datasets.includes(current))datasetFilter.value=current}
function findModel(name){for(const group of Object.keys(DATA)){const model=DATA[group].find(m=>m.name===name);if(model)return {model,group}}}

function onCompare(e){
  const name=e.target.dataset.name,found=findModel(name);
  if(e.target.checked){const first=selected.size?findModel([...selected][0]):null;if(first&&first.group!==found.group){e.target.checked=false;showToast('仅支持同一评测任务内的模型对比');return}if(selected.size>=3){e.target.checked=false;showToast('最多同时对比 3 个模型');return}selected.add(name);showToast(`${name} 已加入对比`)}else selected.delete(name);renderCompareTray();
}
function renderCompareTray(){const tray=document.querySelector('#compareTray'),button=document.querySelector('#openCompare');tray.hidden=selected.size===0;document.querySelector('#compareCount').textContent=selected.size;document.querySelector('#compareChips').innerHTML=[...selected].map((name,i)=>`<span class="compare-chip"><i style="background:${COLORS[i]}"></i>${esc(name)}<button data-remove="${esc(name)}" aria-label="移除 ${esc(name)}">×</button></span>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{selected.delete(b.dataset.remove);renderCompareTray();renderTable()}));button.disabled=selected.size<2;button.textContent=selected.size<2?'再选择 1 个模型':'立即对比 →'}

function renderTop10(){const metric=rankingMetric[task],models=sortModels(DATA[task],metric).slice(0,10),values=models.map(m=>metricValue(m,metric));document.querySelector('#top10Task').textContent=task.toUpperCase();document.querySelector('#rankMetric').textContent=`${metricLabel(metric)} ${metricArrow(metric)}`;document.querySelector('#top10Chart').innerHTML=models.map((m,i)=>`<button class="top10-row" data-name="${esc(m.name)}"><span class="top10-rank">${rankMotion(m.name,i+1)}</span><span class="top10-main"><span class="top10-label"><b>${esc(m.name)}</b><em>${formatMetric(metricValue(m,metric),metric)}</em></span><span class="top10-track"><i style="width:${magnitudePercent(metricValue(m,metric),values)}%"></i></span></span></button>`).join('');document.querySelectorAll('.top10-row').forEach(row=>row.addEventListener('click',()=>openModel(row.dataset.name)))}
function showToast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2200)}

function openModel(name){const found=findModel(name);if(!found)return;const {model,group}=found;setLogo(document.querySelector('#drawerLogo'),model);document.querySelector('#drawerTask').textContent=`${group.toUpperCase()} / MODEL PROFILE`;document.querySelector('#drawerName').textContent=model.name;document.querySelector('#drawerOrg').textContent=`${model.org} · ${model.kind==='open'?'开源模型':'商业 API'}`;renderModelDetails(model,group);const page=document.querySelector('#modelDrawer');page.classList.add('open');page.setAttribute('aria-hidden','false');page.scrollTop=0;document.querySelector('.content').hidden=true;document.querySelector('#compareTray').hidden=true;document.querySelector('#sidebar').classList.remove('open');if(location.hash!==`#model/${encodeURIComponent(name)}`)location.hash=`model/${encodeURIComponent(name)}`;document.querySelector('#drawerClose').focus()}
function closeModel(){const page=document.querySelector('#modelDrawer');page.classList.remove('open');page.setAttribute('aria-hidden','true');document.querySelector('.content').hidden=false;renderCompareTray();if(location.hash.startsWith('#model/'))location.hash='overview'}
function modelRoute(){if(location.hash.startsWith('#model/')){try{const name=decodeURIComponent(location.hash.slice(7));if(findModel(name))openModel(name);else{closeModel();showToast('未找到该模型')}}catch{closeModel()}}else closeModel()}
window.addEventListener('hashchange',modelRoute);
function assetUrl(value){try{const url=new URL(value,location.href);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}}
function logoMarkup(model,extraClass=''){const image=assetUrl(model.logoImage);return `<span class="model-logo${image?' has-image':''}${extraClass?' '+esc(extraClass):''}">${image?`<img src="${esc(image)}" alt="${esc(model.org)} Logo" loading="lazy"><span class="logo-fallback" hidden>${esc(model.logo)}</span>`:esc(model.logo)}</span>`}
function bindLogoFallback(root){root.querySelectorAll('.model-logo img').forEach(image=>image.addEventListener('error',()=>{const logo=image.closest('.model-logo'),fallback=logo?.querySelector('.logo-fallback');image.hidden=true;logo?.classList.remove('has-image');if(fallback)fallback.hidden=false},{once:true}))}
function setLogo(element,model){const image=assetUrl(model.logoImage);element.classList.toggle('has-image',Boolean(image));element.innerHTML=image?`<img src="${esc(image)}" alt="${esc(model.org)} Logo"><span class="logo-fallback" hidden>${esc(model.logo)}</span>`:esc(model.logo);bindLogoFallback(element)}
function renderIntroduction(model){const info=model.introduction||{},architecture=info.architecture||{},image=architecture.image?assetUrl(architecture.image):'';document.querySelector('#modelIntroduction').innerHTML=`<div class="intro-copy"><div class="section-index">01 / MODEL OVERVIEW</div><h3>模型介绍</h3><p>${esc(info.summary||'模型介绍待补充。')}</p><dl class="model-specs">${Object.entries(info.specifications||{}).map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value||'待补充')}</dd></div>`).join('')}</dl><div class="model-links">${(info.links||[]).map(link=>{const href=assetUrl(typeof link==='string'?link:link.url),label=typeof link==='string'?'识别结果':(link.label||'相关链接');return href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:''}).join('')}</div></div><figure class="architecture">${image?`<img src="${esc(image)}" alt="${esc(architecture.alt||model.name+' 架构图')}" loading="lazy"><div class="architecture-placeholder" hidden>架构图暂无法加载</div>`:'<div class="architecture-placeholder"><span>◇ → ◇ → ◇</span><strong>模型架构图</strong><small>待补充</small></div>'}<figcaption>${esc(architecture.caption||'模型架构与推理流程')}</figcaption></figure>`;document.querySelector('.architecture img')?.addEventListener('error',event=>{event.target.hidden=true;event.target.nextElementSibling.hidden=false})}
function renderModelDetails(model,group){
  renderIntroduction(model);
  const kpis=[...Object.entries(model.metrics).map(([key,value])=>[`${metricLabel(key)} ${metricArrow(key)}`,formatMetric(value,key)]),['每小时成本',model.cost],['测试集',`${model.datasets.length} SETS`]];document.querySelector('#detailKpis').innerHTML=kpis.map(([label,value])=>`<article class="detail-kpi"><span>${esc(label)}</span><strong>${esc(value)}</strong></article>`).join('');
  const keys=[...new Set(model.datasets.flatMap(dataset=>Object.keys(dataset.metrics)))];
  document.querySelector('#detailHead').innerHTML=`<tr><th>测试集</th><th>语言 / 场景</th>${keys.map(key=>`<th>${esc(metricLabel(key))} ${metricArrow(key)}</th>`).join('')}</tr>`;
  document.querySelector('#detailBody').innerHTML=model.datasets.map(dataset=>`<tr><td class="dataset-name">${esc(dataset.name)}<small>${esc(dataset.size)}</small></td><td>${esc(dataset.scenario)}</td>${keys.map(key=>`<td>${dataset.metrics[key]!=null?formatMetric(dataset.metrics[key],key):'—'}</td>`).join('')}</tr>`).join('');
}

function comparisonWidth(value,values,key){const min=Math.min(...values),max=Math.max(...values);if(max===min)return 100;const quality=LOWER_IS_BETTER.has(key)?(max-value)/(max-min):(value-min)/(max-min);return 48+quality*52}
function isBest(value,values,key){return value===(LOWER_IS_BETTER.has(key)?Math.min(...values):Math.max(...values))}
function renderComparePage(){
  const items=[...selected].map(findModel).filter(Boolean);if(items.length<2)return;const group=items[0].group,models=items.map(x=>x.model),metricCandidates=group==='asr'?['wer','cer','rtf','latency_ms']:['mos','sim','wer','rtf','latency_ms'],metrics=metricCandidates.filter(key=>models.every(m=>Number.isFinite(metricValue(m,key))));document.querySelector('#compareTask').textContent=group.toUpperCase();
  const wins=new Map(models.map(m=>[m.name,0]));metrics.forEach(key=>{const values=models.map(m=>metricValue(m,key)),best=LOWER_IS_BETTER.has(key)?Math.min(...values):Math.max(...values);models.filter(m=>metricValue(m,key)===best).forEach(m=>wins.set(m.name,wins.get(m.name)+1))});
  const compareModels=document.querySelector('#compareModels');compareModels.innerHTML=models.map((m,i)=>`<article class="compare-model-card" style="--model-color:${COLORS[i]}"><div class="compare-model-id">${logoMarkup(m,'compare-logo')}<div><b>${esc(m.name)}</b><small>${esc(m.org)} · ${m.kind==='open'?'开源':'API'}</small></div></div><div class="win-score"><strong>${wins.get(m.name)}</strong><span>项领先</span></div></article>`).join('');bindLogoFallback(compareModels);
  document.querySelector('#compareMetricGrid').innerHTML=metrics.map(key=>{const values=models.map(m=>metricValue(m,key));return `<article class="compare-metric-card"><header><div><span>${metricLabel(key)} ${metricArrow(key)}</span><h3>${METRIC_NAMES[key]||metricLabel(key)}</h3></div><em>${LOWER_IS_BETTER.has(key)?'越低越好':'越高越好'}</em></header><div class="metric-bars">${models.map((m,i)=>{const value=metricValue(m,key),best=isBest(value,values,key);return `<div class="metric-bar-row"><span>${esc(m.name)}</span><div class="metric-bar-track"><i style="width:${comparisonWidth(value,values,key)}%;background:${COLORS[i]}"></i></div><b class="${best?'winner':''}">${formatMetric(value,key)}${best?'<sup>BEST</sup>':''}</b></div>`}).join('')}</div></article>`}).join('');renderRadar(models,group,metrics);renderDatasetComparison(models,group)
}
function renderRadar(models,group,metrics){
  const size=360,cx=180,cy=172,radius=118,axisCount=metrics.length,groupModels=DATA[group];
  const point=(index,r)=>{const angle=-Math.PI/2+index*Math.PI*2/axisCount;return [cx+Math.cos(angle)*r,cy+Math.sin(angle)*r]};
  const rings=[.25,.5,.75,1].map(scale=>`<polygon points="${metrics.map((_,i)=>point(i,radius*scale).join(',')).join(' ')}"/>`).join('');
  const axes=metrics.map((key,i)=>{const [x,y]=point(i,radius),[lx,ly]=point(i,radius+27);return `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}"/><text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle">${metricLabel(key)} ${metricArrow(key)}</text>`}).join('');
  const shapes=models.map((model,modelIndex)=>{const points=metrics.map((key,i)=>{const values=groupModels.map(m=>metricValue(m,key)),quality=qualityPercent(metricValue(model,key),values,key)/100;return point(i,radius*quality).join(',')}).join(' ');return `<polygon class="radar-model" points="${points}" style="--radar-color:${COLORS[modelIndex]}"/>`}).join('');
  document.querySelector('#compareRadar').innerHTML=`<svg viewBox="0 0 ${size} ${size}" role="img" aria-label="所选模型多维指标雷达图"><g class="radar-grid-lines">${rings}${axes}</g>${shapes}<circle cx="${cx}" cy="${cy}" r="3" class="radar-center"/></svg><div class="radar-key">${models.map((m,i)=>`<span><i style="background:${COLORS[i]}"></i>${esc(m.name)}</span>`).join('')}</div>`;
}
function renderDatasetComparison(models,group){
  const datasetNames=[...new Set(models.flatMap(m=>m.datasets.map(d=>d.name)))],keys=group==='asr'?['error','rtf','latency_ms']:['mos','wer','sim'],rows=[];
  datasetNames.forEach(datasetName=>keys.forEach(requested=>{const cells=models.map(m=>{const ds=m.datasets.find(d=>d.name===datasetName);if(!ds)return null;const key=requested==='error'?(ds.metrics.wer!=null?'wer':'cer'):requested;return ds.metrics[key]!=null?{key,value:Number(ds.metrics[key])}:null});if(cells.every(Boolean)){const key=cells[0].key,values=cells.map(c=>c.value);rows.push(`<tr><td><b>${esc(datasetName)}</b><small>${metricLabel(key)} ${metricArrow(key)}</small></td>${cells.map((c,i)=>{const width=comparisonWidth(c.value,values,key);return `<td><div class="matrix-cell ${isBest(c.value,values,key)?'best':''}" style="--model-color:${COLORS[i]};--heat:${Math.round(5+(width-48)/52*17)}%"><span>${formatMetric(c.value,key)}</span><i style="width:${width}%"></i></div></td>`}).join('')}</tr>`)}}));
  document.querySelector('#compareDatasetMatrix').innerHTML=`<table><thead><tr><th>测试集 / 指标</th>${models.map((m,i)=>`<th><i style="background:${COLORS[i]}"></i>${esc(m.name)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`
}
function openCompare(){if(selected.size<2)return;renderComparePage();document.querySelector('#comparePage').hidden=false;document.body.classList.add('body-locked');document.querySelector('#comparePage').scrollTop=0}
function closeCompare(){document.querySelector('#comparePage').hidden=true;document.body.classList.remove('body-locked')}

function normalizeMetrics(metrics={}){return Object.fromEntries(Object.entries(metrics).map(([key,value])=>[key.toLowerCase(),Number(value)]).filter(([,value])=>Number.isFinite(value)))}
function normalizeModel(raw,group){const metrics=normalizeMetrics(raw.metrics),primary=rankingMetric[group];if(metrics[primary]==null)return null;const score=Number(metrics[primary]),datasets=(raw.datasets||[]).map(d=>({...d,name:d.name||'Unnamed',metrics:normalizeMetrics(d.metrics)})),initials=String(raw.name).split(/[\s-_]+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();return {introduction:raw.introduction||{},name:String(raw.name),org:String(raw.org||'—'),kind:String(raw.kind).toLowerCase()==='api'?'api':'open',logo:String(raw.logo||initials),logoImage:String(raw.logo_image||''),score,metrics,rtf:Number(metrics.rtf||0),cost:raw.cost??'—',datasets}}
function normalizePayload(payload){rankingMetric={asr:String(payload.rankingMetrics?.asr||'wer').toLowerCase(),tts:String(payload.rankingMetrics?.tts||'mos').toLowerCase()};const groups={asr:[],tts:[]};(payload.models||[]).forEach(raw=>{const group=String(raw.task||'').toLowerCase();if(groups[group]){const model=normalizeModel(raw,group);if(model)groups[group].push(model)}});if(!groups.asr.length&&!groups.tts.length)throw new Error('固定文件中没有可用的 ASR/TTS 模型');groups.asr=sortModels(groups.asr,rankingMetric.asr);groups.tts=sortModels(groups.tts,rankingMetric.tts);return groups}
function renderDatasetList(){const counts=new Map();for(const group of ['asr','tts'])DATA[group].forEach(model=>model.datasets.forEach(d=>{const id=`${group}:${d.name}`,old=counts.get(id)||{group,name:d.name,scenario:d.scenario,size:d.size,count:0};old.count++;counts.set(id,old)}));const all=[...counts.values()].sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name)),datasets=all.slice(0,3),max=Math.max(1,...datasets.map(d=>d.count)),list=document.querySelector('#datasetList');list.innerHTML=datasets.map((d,i)=>`<button data-dataset="${esc(d.name)}" data-group="${d.group}"><span class="dataset-icon ${i===1?'violet':i===2?'orange':''}">${String(i+1).padStart(2,'0')}</span><span><b>${esc(d.name)}</b><small>${d.group.toUpperCase()} · ${esc(d.size)} · ${esc(d.scenario)}</small><i class="dataset-coverage" style="--coverage:${d.count/max*100}%"></i></span><em>${d.count}</em></button>`).join('');list.querySelectorAll('[data-dataset]').forEach(button=>button.addEventListener('click',()=>showDatasetRanking(button.dataset.group,button.dataset.dataset)));document.querySelector('#datasetMoreCount').textContent=all.length}
function updateSummary(){const asr=DATA.asr[0],tts=DATA.tts[0],all=[...DATA.asr,...DATA.tts];document.querySelector('#asrBestDirection').textContent=`${metricLabel(rankingMetric.asr)} ${metricArrow(rankingMetric.asr)}`;document.querySelector('#asrBestValue').textContent=asr?formatMetric(metricValue(asr,rankingMetric.asr),rankingMetric.asr):'—';document.querySelector('#asrBestUnit').textContent=metricLabel(rankingMetric.asr);document.querySelector('#asrBestModel').textContent=asr?.name||'无数据';document.querySelector('#ttsBestDirection').textContent=`${metricLabel(rankingMetric.tts)} ${metricArrow(rankingMetric.tts)}`;document.querySelector('#ttsBestValue').textContent=tts?formatMetric(metricValue(tts,rankingMetric.tts),rankingMetric.tts):'—';document.querySelector('#ttsBestUnit').textContent=metricLabel(rankingMetric.tts);document.querySelector('#ttsBestModel').textContent=tts?.name||'无数据';const fastest=all.filter(m=>m.rtf>0).sort((a,b)=>a.rtf-b.rtf)[0];document.querySelector('#rtfBestValue').textContent=fastest?formatMetric(fastest.rtf,'rtf'):'—';document.querySelector('#rtfBestModel').textContent=fastest?.name||'无数据';const a=new Set(DATA.asr.flatMap(m=>m.datasets.map(d=>d.name))),t=new Set(DATA.tts.flatMap(m=>m.datasets.map(d=>d.name))),total=a.size+t.size;document.querySelector('#datasetCount').textContent=total;document.querySelector('#datasetSplit').innerHTML=`ASR ${a.size} <span>·</span> TTS ${t.size}`}
function refreshAll(){if(!DATA[task].length)task=DATA.asr.length?'asr':'tts';setTask(task);updateSummary();renderDatasetList();renderCompareTray()}
async function readDataJson(url){const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw new Error(`${url}: HTTP ${response.status}`);try{return await response.json()}catch{throw new Error(`${url}: JSON 格式错误`)}}
async function loadModelPayload(){const indexUrl=new URL('./data/index.json',location.href),index=await readDataJson(indexUrl);if(index.schemaVersion!==1||!Array.isArray(index.modelFiles)||!index.modelFiles.length)throw new Error('模型索引无效，请运行 node scripts/build-data-index.cjs');const models=await Promise.all(index.modelFiles.map(file=>readDataJson(new URL(file,indexUrl))));return {...index,models}}
async function loadFixedData(){try{DATA=normalizePayload(await loadModelPayload());refreshAll();modelRoute();document.querySelector('#sourceSummary').textContent='点击模型查看各测试集指标 · 勾选 2–3 个模型进行全指标对比';document.querySelector('#modelTotal').textContent=`${DATA.asr.length+DATA.tts.length} MODELS`}catch(error){body.innerHTML='<tr><td colspan="4" class="empty-state">评测结果读取失败，请通过本地服务器访问页面</td></tr>';showToast(error.message)}}

document.querySelectorAll('.segmented [data-task]').forEach(b=>b.addEventListener('click',()=>setTask(b.dataset.task)));document.querySelectorAll('.theme-toggle').forEach(button=>button.addEventListener('click',toggleTheme));typeFilter.addEventListener('change',renderTable);datasetFilter.addEventListener('change',renderTable);document.querySelector('#mobileMenu').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));document.querySelector('#openCompare').addEventListener('click',openCompare);document.querySelector('#compareBack').addEventListener('click',closeCompare);
const overlay=document.querySelector('#commandOverlay'),input=document.querySelector('#commandInput'),results=document.querySelector('#commandResults');let searchMode='all';function openSearch(mode='all'){searchMode=mode;overlay.hidden=false;input.value='';input.placeholder=mode==='datasets'?'搜索数据集…':'搜索模型、数据集或指标…';fillResults('');setTimeout(()=>input.focus(),0)}function closeSearch(){overlay.hidden=true}function datasetCatalog(){return ['asr','tts'].flatMap(group=>{const seen=new Map();DATA[group].forEach(model=>model.datasets.forEach(d=>{if(!seen.has(d.name))seen.set(d.name,{group,name:d.name,scenario:d.scenario,size:d.size})}));return [...seen.values()]})}
function datasetRanking(group,name){const entries=DATA[group].map(model=>{const result=model.datasets.find(d=>d.name===name);if(!result)return null;const key=datasetMetricKey(group,result);return {model,key,value:Number(result.metrics[key])}}).filter(x=>x&&Number.isFinite(x.value)),key=entries[0]?.key||rankingMetric[group];entries.sort((a,b)=>LOWER_IS_BETTER.has(key)?a.value-b.value:b.value-a.value);return {key,entries}}
function showDatasetRanking(group,name){closeModel();if(task!==group)setTask(group);datasetFilter.value=name;renderTable();document.querySelector('#leaderboard').scrollIntoView({behavior:'smooth',block:'start'})}
function fillResults(q){const query=q.trim().toLowerCase(),models=searchMode==='datasets'?[]:[...DATA.asr,...DATA.tts].filter(m=>m.name.toLowerCase().includes(query)).slice(0,6),showDatasets=searchMode==='datasets'||Boolean(query),datasets=showDatasets?datasetCatalog().filter(d=>!query||`${d.name} ${d.scenario}`.toLowerCase().includes(query)).sort((a,b)=>a.group.localeCompare(b.group)||a.name.localeCompare(b.name)).map(d=>({...d,...datasetRanking(d.group,d.name)})).filter(d=>d.entries.length):[];const modelHtml=models.map(m=>`<button class="command-result" data-name="${esc(m.name)}"><span>${esc(m.name)}</span><small>${esc(m.org)} · ${m.kind==='open'?'开源':'API'}</small></button>`).join(''),datasetHtml=datasets.map(d=>`<div class="command-dataset"><button class="command-result command-dataset-head" data-dataset="${esc(d.name)}" data-group="${d.group}"><span><b>${esc(d.name)}</b><small>${[d.group.toUpperCase(),d.scenario,d.size].filter(Boolean).map(esc).join(' · ')} · ${metricLabel(d.key)} ${metricArrow(d.key)}</small></span><small>在榜单中查看 →</small></button>${d.entries.map((x,i)=>`<button class="command-result command-rank" data-name="${esc(x.model.name)}"><span><i>${String(i+1).padStart(2,'0')}</i>${esc(x.model.name)}<small>${esc(x.model.org)} · ${x.model.kind==='open'?'开源':'API'}</small></span><b>${formatMetric(x.value,d.key)}</b></button>`).join('')}</div>`).join(''),sections=(models.length?'<div class="command-group">模型</div>'+modelHtml:'')+(datasets.length?`<div class="command-group">数据集 · ${datasets.length} 项</div>`+datasetHtml:'');results.innerHTML=sections||'<button class="command-result"><span>未找到匹配结果</span></button>';results.querySelectorAll('[data-name]').forEach(b=>b.addEventListener('click',()=>{closeSearch();openModel(b.dataset.name)}));results.querySelectorAll('[data-dataset]').forEach(b=>b.addEventListener('click',()=>{closeSearch();showDatasetRanking(b.dataset.group,b.dataset.dataset)}))}document.querySelector('#searchTrigger').addEventListener('click',()=>openSearch('all'));document.querySelector('#datasetMore').addEventListener('click',()=>openSearch('datasets'));input.addEventListener('input',()=>fillResults(input.value));overlay.addEventListener('click',e=>{if(e.target===overlay)closeSearch()});document.querySelector('#drawerClose').addEventListener('click',closeModel);document.querySelector('#drawerBackdrop').addEventListener('click',closeModel);document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch('all')}if(e.key==='Escape'){closeSearch();closeModel();if(!document.querySelector('#comparePage').hidden)closeCompare()}});
loadFixedData();
